export const BODY: string = "\n<p>تدوير زوايا صورة يستغرق بضع دقائق فقط: ترفع الصورة وتسحب منزلقًا لتثبيت المنحنى وتنزّل النتيجة المنعمة.</p>\n<p>هذا البرنامج التعليمي يمر بالعملية كاملة خطوة بخطوة: يغطي منزلق نصف القطر والضبط لكل زاوية واختصار الدائرة الكاملة وخيارات التعبئة وصيغ التصدير التي تبقي الزوايا شفافة.</p>\n<p>في النهاية ستستطيع صنع صورة رمزية مدورة أو صورة بطاقة أو لافتة على شكل حبة دواء على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: اختر الشكل</h2>\n<p>قرر أي شكل تحتاجه قبل فتح الأداة: دائرة تناسب صورة رمزية، وتدوير ناعم يناسب بطاقة، وحبة دواء تناسب لافتة أو شارة.</p>\n<p>راجع الوجهة أيضًا: قد يتطلب مكان ملف شخصي دائرة، بينما قد تحتاج بطاقة مدونة فقط الزاويتين العلويتين مدورتين. واستخدم الصورة الأصلية، لا نسخة مضغوطة: التدوير من أصل حاد يبقي الحواف المنحنية ناعمة، بينما تدوير نسخة ناعمة يجعل المنحنيات تبدو خشنة.</p>\n<p>افتح <a href=\"/ar/tadweer-zawaya-as-sura/\">أداة تدوير زوايا الصورة</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">دوّر زوايا صورة في خمس خطوات</h2>\n<p>العملية نفسها لتدوير ناعم ولدائرة كاملة: ارفع الصورة وثبّت نصف القطر واختر التعبئة وراجع المعاينة ونزّل.</p>\n<p>خذ وقتك مع نصف القطر: تغيير صغير في القيمة قد يصنع فرقًا كبيرًا في إحساس الشكل، فراقب المعاينة وأنت تسحب. وافتح الملف المنزّل مرة قبل استخدامه، وتأكد من أن الزوايا تبدو ناعمة وأن لا شيء مهم قُص.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اسحب منزلق نصف قطر كل الزوايا لتثبيت المنحنى، مراقبًا قراءة البكسلات الحية وأنت تضبطه.</li>\n<li>فعّل وضع لكل زاوية لتثبيت أنصاف أقطار مختلفة، أو استخدم اختصار الدائرة الكاملة / الحبة لشكل دائري أو حبة دواء.</li>\n<li>اختر شفاف في تعبئة الزاوية الخارجية لزوايا شفافة، أو لونًا صلبًا لخلفية معبأة.</li>\n<li>اختر صيغة التصدير، PNG أو WebP للحفاظ على الشفافية، ثم اضغط تنزيل لحفظ النتيجة.</li>\n</ol>\n<h2 id=\"setting-radius\">كيف تثبت نصف قطر الزاوية</h2>\n<p>يقرر منزلق نصف القطر مدى استدارة الزوايا: قيمة صغيرة تعطي تنعيمًا خفيفًا، بينما قيمة كبيرة تحول الزوايا إلى منحنيات عميقة.</p>\n<p>نصف قطر 10 إلى 20 بكسلًا يناسب البطاقات والمصغرات ولقطات الشاشة: التدوير لطيف وما زالت الصورة تبدو كمستطيل بحواف ناعمة. ونصف قطر 50 إلى 100 بكسل يعطي مظهرًا مدورًا بوضوح: يناسب الصور الرمزية والمنشورات الاجتماعية ورسوم التطبيقات، حيث الشكل جزء من التصميم.</p>\n<p>راقب قراءة البكسلات الحية بجانب المنزلق: تُظهر قيمة نصف القطر الدقيقة، فتستطيع إعادة إنتاج نفس التدوير على صورة أخرى لاحقًا.</p>\n<h2 id=\"per-corner-mode\">كيف تستخدم وضع لكل زاوية</h2>\n<p>يسمح وضع لكل زاوية بتثبيت نصف قطر مختلف لكل زاوية: عند تفعيله تظهر أربعة منزلقات منفصلة، واحد لكل زاوية من الصورة.</p>\n<p>بطاقة مدونة هي الحالة الكلاسيكية: دوّر الزاويتين العلويتين واترك السفليتين مربعتين، لتستقر الصورة جيدًا في أعلى البطاقة. وعند تعطيل وضع لكل زاوية تعود إلى نصف قطر واحد لكل الزوايا: تُحفظ القيم الفردية بينما الوضع مطفأ، فتستطيع إعادة تفعيله دون فقدانها.</p>\n<p>استخدم الضبط لكل زاوية باعتدال: تصميم بأربعة أنصاف أقطار مختلفة يبدو كحادث، بينما زاوية أو زاويتان مدورتان مع البقية مربعة تبدو مقصودة.</p>\n<h2 id=\"full-circle-shortcut\">كيف تستخدم اختصار الدائرة الكاملة / الحبة</h2>\n<p>يثبت اختصار الدائرة الكاملة نصف القطر عند نصف حجم الصورة بنقرة واحدة: في صورة مربعة يخلق دائرة مثالية، وفي مستطيل يخلق شكل حبة دواء.</p>\n<p>لدائرة نظيفة، قص الصورة إلى 1:1 أولًا: مصدر مربع مع الاختصار يعطي صورة رمزية دائرية تمامًا تناسب أي مكان ملف شخصي. وفي صورة مستطيلة، يخلق الاختصار حبة دواء: مستطيل بطرفين مدورين تمامًا. وتناسب الحبوب الأزرار والشارات واللافتات.</p>\n<p>راجع النتيجة قبل التنزيل: شكل حبة دواء قد يبدو أنيقًا، لكنه قد يقطع أيضًا محتوى مهمًا على جانبي صورة عريضة.</p>\n<h2 id=\"choosing-fill\">كيف تختار تعبئة شفافة أو صلبة</h2>\n<p>عندما تُقص الزوايا، يجب ملء المساحة الفارغة: شفاف يترك الزوايا شفافة، بينما صلب يملؤها بلون.</p>\n<p>اختر شفافًا لرسوم الويب والصور الرمزية والتراكبات: تندمج الصورة مع أي خلفية، لأن الزوايا تُظهر ما خلف الصورة. واختر صلبًا عندما لا تدعم الوجهة الشفافية: تعبئة بيضاء صلبة تجعل الصورة تبدو كصورة مدورة فوق بطاقة بيضاء، ما يناسب المستندات والمطبوعات.</p>\n<p>وإذا ضغطت شفافًا مع اختيار JPG، تغيّر الأداة الصيغة تلقائيًا: JPG ليس له شفافية، فتبدله إلى PNG أو WebP.</p>\n<h2 id=\"choosing-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر PNG لأنقى نتيجة مع شفافية: دون فقدان، فتبقى الحواف المنحنية ناعمة، ويعمل في كل مكان، بما فيه المتصفحات القديمة.</p>\n<p>اختر WebP عندما تريد ملفات صغيرة مع شفافية: يعطي ملفات أصغر من PNG بنفس الزوايا الشفافة، مع أن بعض الأنظمة القديمة ترفضه. واختر JPG فقط عندما تكون للزوايا تعبئة صلبة: JPG ليس له شفافية، فتصدير شفاف كـJPG ينتهي بتعبئة صلبة، قد لا تطابق خلفيتك.</p>\n<p>لرسوم ويب مدورة، PNG أو WebP هو الخيار الصحيح. ولصورة مدورة فوق صفحة بيضاء، يعمل JPG بتعبئة بيضاء جيدًا.</p>\n<h2 id=\"previewing\">المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل: تحقق من أن الزوايا ناعمة وأن نصف القطر يبدو جيدًا وأن لا شيء مهم قُص.</p>\n<p>قرّب على زاوية وراقب المنحنى: قوس ناعم يعني أن التدوير نجح جيدًا، بينما حافة مسننة تعني أن المصدر كان صغيرًا جدًا أو ناعمًا جدًا. وراجع التعبئة فوق الخلفية التي ستعيش عليها الصورة: زاوية شفافة تبدو جيدة في أي مكان، بينما تعبئة صلبة تطابق فقط اللون الذي حُددت له.</p>\n<p>وإذا لم يبدُ نصف القطر جيدًا، اضبط المنزلق وراجع مجددًا: تغيير صغير في القيمة قد يصنع فرقًا كبيرًا في إحساس الشكل.</p>\n<h2 id=\"rounding-for-avatar\">تدوير الزوايا لصورة رمزية</h2>\n<p>قص الصورة إلى مربع أولًا، بـ<a href=\"/ar/qass-as-suwar/\">قاص الصور</a>: قص 1:1 مع الوجه في الوسط يعطي أفضل نقطة بداية لصورة رمزية دائرية.</p>\n<p>ارفع الصورة المربعة واضغط اختصار الدائرة الكاملة: يقفز نصف القطر إلى نصف حجم الصورة وتتحول الصورة إلى دائرة مثالية. وأبقِ الوجه جيدًا داخل الإطار: تُقص الزوايا، فوجه قرب الحافة قد يفقد أذنًا أو جزءًا من الشعر بالمنحنى.</p>\n<p>صدّر كـPNG أو WebP: تحافظ الشفافية على الزوايا شفافة، فتندمج الصورة الرمزية مع أي خلفية ملف شخصي، فاتحة أو داكنة.</p>\n<h2 id=\"rounding-for-cards\">تدوير الزوايا للبطاقات والواجهة</h2>\n<p>طابق نصف قطر الصورة مع نصف قطر البطاقة: صورة بنصف قطر 16 بكسلًا داخل بطاقة بنصف قطر 16 بكسلًا تبدو مثالية، بينما أنصاف الأقطار المختلفة تبدو غير متطابقة.</p>\n<p>لبطاقة مدونة، دوّر الزاويتين العلويتين واترك السفليتين مربعتين: فعّل وضع لكل زاوية وثبّت أنصاف الأقطار العلوية واترك السفلية صفرًا. وأبقِ نصف القطر ثابتًا عبر كل بطاقات مجموعة: شبكة بطاقات بزوايا متطابقة تبدو احترافية، بينما أنصاف الأقطار المختلطة تبدو عشوائية.</p>\n<p>صدّر صور البطاقات كـPNG أو WebP عندما تكون البطاقة فوق خلفية ملونة: تحافظ الشفافية على الزوايا نظيفة فوق أي لون.</p>\n<h2 id=\"rounding-screenshots\">تدوير الزوايا في لقطة شاشة</h2>\n<p>الصق لقطة مباشرة بـCtrl+V لتتخطى خطوة الحفظ: تظهر الصورة في الأداة فورًا، جاهزة للتدوير.</p>\n<p>استخدم نصف قطر صغير 10 إلى 20 بكسلًا للقطات: تدوير ناعم يجعل اللقطة تبدو كبطاقة تطبيق حديثة دون إخفاء أي محتوى. وصدّر اللقطات المدورة كـPNG: الصيغة دون فقدان تبقي النص الصغير حادًا، وهو أمر مهم عندما تُظهر اللقطة ضبطًا أو رسالة خطأ.</p>\n<p>أبقِ نصف القطر ثابتًا عبر كل لقطات دليل: الزوايا المتطابقة تساعد القارئ على متابعة الخطوات، بينما أنصاف الأقطار المختلطة تشتت عن التعليمات.</p>\n<h2 id=\"rounding-on-mobile\">تدوير الزوايا على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع تدوير صورة على الهاتف نفسه الذي التقطها: ارفع الصورة من معرضك واسحب منزلق نصف القطر ونزّل النتيجة.</p>\n<p>استخدم اختصار الدائرة الكاملة للصور الرمزية على شاشة صغيرة: لمسة واحدة تحول صورة مربعة إلى دائرة، أسرع من سحب المنزلق إلى القيمة الدقيقة. وراجع المعاينة بالحجم الكامل قبل التنزيل: نصف قطر يبدو لطيفًا على شاشة هاتف صغيرة قد يبدو أكثر وضوحًا عند رؤيته على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك تعيين الصورة المدورة كصورة ملف شخصي أو مشاركتها مباشرة.</p>\n<h2 id=\"troubleshooting\">كيف تحل مشاكل التدوير الشائعة</h2>\n<p>إذا أظهرت الزوايا خلفية بيضاء بدل الشفافية، راجع صيغة التصدير: JPG ليس له شفافية، فصدّر كـPNG أو WebP للحفاظ على الزوايا شفافة.</p>\n<p>وإذا كان الشكل حبة دواء بدل دائرة، فصورة المصدر مستطيلة: قصها إلى مربع أولًا ثم طبق اختصار الدائرة الكاملة. وإذا بدت الزوايا مسننة، فقد تكون صورة المصدر صغيرة جدًا: ابدأ من أصل أعلى دقة وستبدو المنحنيات ناعمة.</p>\n<p>وإذا اختفت قيمك لكل زاوية، راجع إن عطّلت الوضع: تُحفظ القيم بينما الوضع مطفأ، فعند إعادة تفعيله تُستعاد.</p>\n<h2 id=\"combining-with-border\">دمج زوايا مدورة مع حد</h2>\n<p>دوّر الزوايا أولًا ثم أضف حدًا بـ<a href=\"/ar/idafa-itar-ila-as-sura/\">مولد حدود الصور</a>: تقرأ أداة الحدود شكل الصورة، فالتدوير أولًا يبقي الإطار محاذيًا للمنحنى.</p>\n<p>طابق نصف قطر الحد مع نصف قطر الزاوية: حد بنصف قطر 16 بكسلًا حول صورة بنصف قطر 16 بكسلًا يبدو مثاليًا. ولمظهر بطاقة، استخدم حدًا رفيعًا بنصف قطر ناعم: يبدو المزيج كبطاقة تطبيق حديثة، ما يناسب المنشورات الاجتماعية والعروض.</p>\n<p>ولنمط Polaroid، أبقِ الزوايا مربعة: المظهر الكلاسيكي للفيلم الفوري له زوايا حادة، وتدويرها يكسر الجو الرجعي.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لزوايا مدورة أفضل</h2>\n<p>قص إلى الشكل الصحيح قبل التدوير: قص مربع لدائرة وقص عريض لحبة دواء وقص بطاقة لصورة مدونة تبدأ كلها بالقاص.</p>\n<p>راجع المعاينة بالحجم الكامل قبل التنزيل: قرّب على الزوايا وتأكد من أن المنحنيات ناعمة وأن لا شيء مهم قُص. واحفظ الملف المدور باسم واضح، مثل avatar-circulo.png: قد تحتاج نفس الشكل مجددًا، واسم واضح يوفر عليك إعادة العمل.</p>\n<p>احتفظ بالصورة الأصلية دون تدوير: بمجرد قص الزوايا في تصدير، لا يمكن استعادتها من ذلك الملف.</p>\n<h2 id=\"rounding-for-social-post\">تدوير الزوايا لمنشور اجتماعي</h2>\n<p>منشور اجتماعي بزوايا مدورة يبدو حديثًا وودودًا: الحواف الناعمة تطابق البطاقات والأزرار في التطبيق المحيط، فتندمج الصورة مع الواجهة.</p>\n<p>استخدم نصف قطر صغير إلى متوسط لمنشورات الخلاصة: تدوير ناعم 10 إلى 20 بكسلًا ينعّم الصورة دون تغيير طابعها أو إخفاء محتوى. وأبقِ نصف القطر ثابتًا عبر كل منشوراتك: خلاصة تشترك كل صورة فيها في نفس شكل الزاوية تبدو معتنى بها، بينما أنصاف الأقطار المختلطة تبدو عشوائية.</p>\n<p>صدّر الصور الاجتماعية كـJPG عندما تكون للزوايا تعبئة صلبة، أو PNG وWebP عندما تكون شفافة: الصيغة الصحيحة تبقي الزوايا نظيفة فوق أي خلفية.</p>\n<h2 id=\"rounding-for-presentation\">تدوير الزوايا لعرض تقديمي</h2>\n<p>الصور في الشرائح تبدو أفضل بزوايا مدورة: الحواف الناعمة تطابق تصميم الشريحة الحديث، وتبدو الصورة كعنصر مقصود لا كمستطيل ملصوق.</p>\n<p>طابق نصف قطر الصورة مع سمة الشريحة: عرض ببطاقات 16 بكسلًا يحتاج صورًا بنصف قطر 16 بكسلًا، لتتسق الصور والبطاقات. وأبقِ نصف القطر صغيرًا لشرائح تُعرض كبيرة: نصف قطر ضخم على شاشة كبيرة قد يهيمن على الصورة، بينما تدوير ناعم يبقى لطيفًا بأي حجم.</p>\n<p>صدّر صور العرض كـJPG بضبط جودة عالية عندما تكون للزوايا تعبئة صلبة: يجب أن تبقى الصورة حادة عند العرض، وتصدير منخفض الجودة ينعّم الحواف المنحنية.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/zawaya-mudawwara-vs-qass-dairi/\">زوايا مدورة أم قص دائري: صور رمزية وبطاقات</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-tadweer-zawaya-as-suwar/\">دليل تدوير زوايا الصورة الكامل</a>، ولتأطير صورة مدورة استخدم <a href=\"/ar/idafa-itar-ila-as-sura/\">مولد حدود الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أدوّر زوايا صورة على هاتفي؟","answer":"افتح أداة تدوير زوايا الصورة في متصفح هاتفك وارفع الصورة من معرضك واسحب منزلق نصف القطر بإصبعك. واستخدم اختصار الدائرة الكاملة لصورة رمزية دائرية. وصدّر كـPNG أو WebP للحفاظ على الشفافية."},{"question":"ما أفضل نصف قطر لصورة بطاقة؟","answer":"نصف قطر صغير إلى متوسط 10 إلى 20 بكسلًا يناسب معظم البطاقات، معطيًا تنعيمًا خفيفًا دون تغيير الشكل. وطابق نصف قطر الصورة مع نصف قطر البطاقة لمظهر مثالي. ولبطاقة مدونة، دوّر الزاويتين العلويتين فقط."},{"question":"هل يمكنني تدوير زوايا صورة JPG؟","answer":"نعم، لكن الزوايا ستمتلئ بلون صلب، إذ ليس لـJPG شفافية. واختر لون تعبئة يطابق الخلفية التي ستعيش عليها الصورة، أو صدّر كـPNG أو WebP للحفاظ على الزوايا شفافة."},{"question":"كيف أستبدل الصورة دون فقدان ضبط نصف القطر؟","answer":"حمّل الصورة الجديدة بخيار الاستبدال في الأداة، الذي يحافظ على ضبط نصف القطر والتعبئة الحاليين. ثم يمكنك ضبط نصف القطر للصورة الجديدة وتصديرها بنفس الضبط."},{"question":"لماذا تبدو زواياي المدورة مسننة؟","answer":"صورة المصدر غالبًا صغيرة جدًا أو ناعمة جدًا، فتظهر المنحنى كخطوات مرئية. وابدأ من أصل أعلى دقة وستبدو الحواف ناعمة. والتصدير كـPNG يحافظ على المنحنيات أنظف من JPG."},{"question":"هل تدوير الزوايا يغيّر عرض صورتي وارتفاعها؟","answer":"لا، التدوير يقص فقط مناطق الزوايا ويترك العرض والارتفاع دون تغيير. ويحتفظ الملف بنفس الأبعاد بالبكسلات، مع زوايا شفافة أو معبأة بلون صلب."}];
